<div class="table-responsive"><table class="table table-bordered bg-white"><thead><tr><th>ID</th><th>Họ tên</th><th>Email</th><th>Vai trò</th><th>Trạng thái</th><th>Thao tác</th></tr></thead><tbody><?php foreach($users as $u): ?><tr><td><?= (int)$u['id'] ?></td><td><?= e($u['name']) ?></td><td><?= e($u['email']) ?></td><td><?= e($u['role']) ?></td><td><?= e($u['status']) ?></td><td><?php if(Auth::user()['role']==='admin'&&(int)$u['id']!==(int)Auth::user()['id']): ?><form method="post" action="<?= e(base_url('admin/user/update')) ?>" class="d-inline"><?= csrf_field() ?><input type="hidden" name="user_id" value="<?= (int)$u['id'] ?>"><select name="role" class="form-select form-select-sm d-inline w-auto"><?php foreach(['customer','staff','admin'] as $r): ?><option value="<?= $r ?>" <?= $u['role']===$r?'selected':'' ?>><?= $r ?></option><?php endforeach; ?></select><button class="btn btn-sm btn-primary">Lưu</button></form><form method="post" action="<?= e(base_url('admin/user/status')) ?>" class="d-inline"><?= csrf_field() ?><input type="hidden" name="user_id" value="<?= (int)$u['id'] ?>"><input type="hidden" name="status" value="<?= $u['status']==='active'?'locked':'active' ?>"><button class="btn btn-sm btn-outline-secondary"><?= $u['status']==='active'?'Khóa':'Mở khóa' ?></button></form><?php else: ?>—<?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div>
